import React, { useEffect, useState } from "react";
import { getCart, checkout } from "../api/api";
import ReceiptModal from "../components/ReceiptModal";
import { jwtDecode } from "jwt-decode";

export default function Checkout() {
  const [cart, setCart] = useState([]);
  const [userInfo, setUserInfo] = useState(null);
  const [receipt, setReceipt] = useState(null);

  useEffect(() => {
    const fetchCart = async () => {
      const data = await getCart();
      setCart(data);

      if (data.length > 0 && data[0].user) {
        setUserInfo(data[0].user);
      }
    };
    fetchCart();
  }, []);

  const handleCheckout = async () => {
    const res = await checkout();
    setReceipt({
      ...res,
      billingTime: new Date().toLocaleString(),
      user: userInfo,
    });
  };

  if (!cart.length) return <p>Your cart is empty.</p>;

  const total = cart.reduce(
    (sum, item) => sum + item.product.price * item.qty,
    0
  );

  return (
    <div className="checkout-container">
      <h2>Checkout</h2>

      {userInfo && (
        <div className="billing-info">
          <p><strong>Name:</strong> {userInfo.name}</p>
          <p><strong>Email:</strong> {userInfo.email}</p>
          <p><strong>Billing Time:</strong> {new Date().toLocaleString()}</p>
        </div>
      )}

      <ul>
        {cart.map((item) => (
          <li key={item._id}>
            {item.product.name} × {item.qty} = ₹
            {item.product.price * item.qty}
          </li>
        ))}
      </ul>

      <h3>Total: ₹{total}</h3>

      <button onClick={handleCheckout}>Pay Now</button>

      {receipt && <ReceiptModal receipt={receipt} />}
    </div>
  );
}
